Func<dynamic, Context, CancellationToken, Task> HandleAsync = async (view, ctx, ct) =>
{
    if (view.Host is not Orc.Game.Cards.CardBase host) { return; }
    if (view.Player is not Orc.Game.Players.Player ended) { return; }

    dynamic self = view.Owner;

    if (!object.ReferenceEquals(host.Owner, ended))
    {
        // 首个回合边界不是拥有者的：施加发生在对手回合——其后拥有者回合结束即递减。
        self.firstOwnerTurnEnd = false;
        return;
    }

    if ((bool)self.firstOwnerTurnEnd)
    {
        // 施加时正处于拥有者回合：本回合结束不递减（skip 消费一次、不进参值面）。
        self.firstOwnerTurnEnd = false;
        return;
    }

    var remaining = Orc.Game.Cards.KeywordRules.GetKeywordValue(host, Orc.Game.Cards.KeywordIds.Suppressed)
        ?? Orc.Game.Cards.SuppressRules.SuppressedDefaultTurns;
    var next = remaining - 1;
    if (next <= 0)
    {
        await host.Keywords.RevokeAsync(Orc.Game.Cards.KeywordIds.Suppressed);
        return;
    }

    host.Keywords.SetValue(Orc.Game.Cards.KeywordIds.Suppressed, next);
};
